export const MAX_SAVE_BYTES=64*1024*1024;export const MAX_CHUNK_DECOMP_BYTES=4*1024*1024;export const MAX_TOTAL_DECOMP_BYTES=96*1024*1024;export const MAX_CHUNKS=512;export const MAX_JSON_DEPTH=48;export const MAX_INFLATED_BYTES=4*1024*1024;export const MAX_RECORDS=8192;export const MAX_SYSTEMS=16384;export const MAX_NAME_LEN=64;export const MAX_USER_LEN=32;export const MAX_ARRAY_LEN=8192;export const MAX_UA_HEX_LEN=32;export function boundedArray(v,max=MAX_ARRAY_LEN){return Array.isArray(v)?v.slice(0,max):[]}export const MAX_PLAUSIBLE_TS=Date.UTC(2100,0,1)/1e3;export const MIN_PLAUSIBLE_TS=Date.UTC(2016,7,9)/1e3;const BIDI_AND_ZERO_WIDTH=/[\u200b-\u200f\u202a-\u202e\u2066-\u2069\u061c\ufeff]/g;export function sanitizeString(v,maxLen){if(typeof v!=="string"||!v.length){return null}const clean=v.replace(/[\x00-\x1f\x7f-\u009f]/g,"").replace(BIDI_AND_ZERO_WIDTH,"");if(!clean.length){return null}const truncated=[...clean].slice(0,maxLen).join("");return truncated.length?truncated:null}export function sanitizeTs(v){return typeof v==="number"&&Number.isFinite(v)&&v>=MIN_PLAUSIBLE_TS&&v<MAX_PLAUSIBLE_TS?v:null}
